  color: var(--color-neutral-700);
  max-width: 600px;
  margin: 0 auto var(--spacing-2xl);
}

.index-contact-grid {
  display: grid;
  gap: var(--spacing-2xl);
  grid-template-columns: 1fr 1fr;
}

.index-contact-info h3,
.index-contact-form-wrapper h3 {
  margin-bottom: var(--spacing-lg);
  color: var(--color-primary-dark);
}

.index-contact-details {
  display: grid;
  gap: var(--spacing-md);
}

.index-contact-details dt {
  font-weight: 600;
  color: var(--color-primary-dark);
  margin-top: var(--spacing-sm);
}

.index-contact-details dd {
  margin: 0;
  color: var(--color-neutral-700);
  line-height: 1.6;
}

.index-contact-details a {
  color: var(--color-primary-dark);
  font-weight: 500;
  text-decoration: none;
}

.index-contact-details a:hover {
  color: var(--color-accent);
  text-decoration: underline;
}

.index-contact-form {
  background-color: var(--color-white);
  padding: var(--spacing-lg);
  border-radius: var(--radius);
  border: 1px solid var(--color-neutral-200);
}

.index-contact-form .form-group {
  margin-bottom: var(--spacing-md);
}

.index-contact-form button {
  width: 100%;
}

@media (max-width: 600px) {
  .index-hero {
    padding: var(--spacing-xl) 0;
  }

  .index-hero-subtitle {
    font-size: 1rem;
  }

  .index-contact-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-xl);
  }

  .index-contact-form {
    padding: var(--spacing-md);
  }
}

@media (min-width: 601px) {
  .index-hero {
    padding: var(--spacing-2xl) 0;
  }

  .index-contact-grid {
    grid-template-columns: 1fr 1fr;
  }
}

